import {ActivityDataElement} from '@hw/hmiweb-activity-data/unbundled/index';
import {IActivityDataElement} from '@hw/hmiweb-activity-data/unbundled/interfaces/IActivityDataElement';
import {IActivityCreationAndDataService} from '@hw/experionservices/unbundled/interfaces/IActivityCreationAndDataService';
import {ActivityDataDataTypes} from '@hw/hmiweb-activity-data/unbundled/interfaces/ActivityDataDataTypes';
import {IPointDataService} from '@hw/experionservices/unbundled/interfaces/IPointDataService';
import {ISubscriptionService} from '@hw/experionservices/unbundled/interfaces/ISubscriptionService';

export class ActivityDataDisplay {
    private _activityDataElement: HTMLElement & IActivityDataElement;

    constructor(private _logger: ILogger,
                private _localization: ILocalisation,
                private _activityCreationAndDataService: IActivityCreationAndDataService,
                private _pointDataService: IPointDataService,
                private _pointDataSubscriptionService: ISubscriptionService) {
        this._activityDataElement = document.getElementById("activityData") as any;
        this.setupListeners();
        ActivityDataElement.register(this._logger, this._localization, this._activityCreationAndDataService, this._pointDataService, this._pointDataSubscriptionService);
        
        this._logger.info(LogGroups.SPA, "ActivityDataDisplay .. created");
    }

    private setupListeners(): void {
        this._logger.info(LogGroups.SPA, "ActivityDataDisplay::setupListeners .. entering");

        if (this._activityDataElement) {
            this._activityDataElement.addEventListener("activity-data-created", () => {
                this.showActivityDataFromURL();
            });
            this._activityDataElement.addEventListener("activity-data-activity-changed", () => {
                this.setPopupTitle();
            });

            this._logger.info(LogGroups.SPA, "ActivityDataDisplay::setupListeners .. added event listeners");
        } else {
            this._logger.error(LogGroups.SPA, "ActivityDataDisplay::setupListeners .. couldn't find ActivityDataElement");
        }
    }

    private showActivityDataFromURL(): void {
        this._logger.info(LogGroups.SPA, "ActivityDataDisplay::showActivityDataFromURL .. entering");

        const queryString = document.location.search;
        let params: string[] = queryString.substring(1).split("&");

        for (let param of params) {
            let parts = param.split(/=(.*)/);

            if (parts[0] == "activitytagname" && parts.length > 1) {
                const activityName = decodeURIComponent(parts[1]);
                this._logger.info(LogGroups.SPA, `ActivityDataDisplay::showActivityDataFromURL .. showing activity "${activityName}"`);
                this._activityDataElement.show(activityName, ActivityDataDataTypes.ActDataTab.General, ActivityDataDataTypes.ActDataType.Activity);
                return;
            }
        }

        this._logger.error(LogGroups.SPA, `ActivityDataDisplay::showActivityDataFromURL .. activitytagname param not found in query string "${document.location.search}"`);
    }

    private setPopupTitle(): void {
        this._logger.info(LogGroups.SPA, "ActivityDataDisplay::setPopupTitle .. entering");

        this._localization.getLocalisedStrings().then((localisedStrings: ILocalisedStrings) => {
            const localizedTitleStart = `${localisedStrings.getStringOrError("View/Edit")} `;
            const localizedTitleDefault = `${localisedStrings.getStringOrError("parameters")}...`;

            if (!this._activityDataElement) {
                document.title = localizedTitleStart + localizedTitleDefault;
                this._logger.error(LogGroups.SPA, `ActivityDataDisplay::setPopupTitle .. couldn't find ActivityDataElement, using default title`);
                return;
            }
    
            const batchId = this._activityDataElement.batchId;
            const parents = this._activityDataElement.activityParents;
            const publicName = this._activityDataElement.activityPublicName;
            const recipeStep = this._activityDataElement.activityRecipeStep;
            let title = localizedTitleStart;

            if (!batchId || !publicName) {
                title += localizedTitleDefault;
            } else {
                // \u205f is alternate whitespace for double space, as consecutive whitespaces are collapsed
                title += batchId + " \u205f|\u205f ";
                if (parents) {
                    title += parents + " > ";
                }
                title += publicName;
                if (recipeStep) {
                    title += "." + recipeStep;
                }
            }

            document.title = title;

            this._logger.info(LogGroups.SPA, `ActivityDataDisplay::setPopupTitle .. set title to "${title}"`);
        });
    }
}
